-- WDN1D1 NPCBot fixed dialogue bilingual text. World only, with server stopped.
-- Exact stock-text guards preserve custom text; no delete/rebuild/owner changes.
SET NAMES utf8mb4;
DROP PROCEDURE IF EXISTS reborn_wdn1d1_localize;
DELIMITER $$
CREATE PROCEDURE reborn_wdn1d1_localize()
BEGIN
 DECLARE EXIT HANDLER FOR SQLEXCEPTION
 BEGIN ROLLBACK; DROP TEMPORARY TABLE IF EXISTS reborn_wdn1d1_texts; RESIGNAL; END;
 IF (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE()
    AND table_name IN('npc_text','npc_text_locale') AND engine='InnoDB')<>2 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='WDN1D1 requires current InnoDB npc_text and npc_text_locale tables';
 END IF;
DROP TEMPORARY TABLE IF EXISTS reborn_wdn1d1_texts;
CREATE TEMPORARY TABLE reborn_wdn1d1_texts(id INT PRIMARY KEY,en LONGTEXT,zh LONGTEXT,bi LONGTEXT) ENGINE=InnoDB;
START TRANSACTION;
UPDATE npc_text n JOIN reborn_wdn1d1_texts s ON s.id=n.ID
 SET n.text0_0=s.bi
 WHERE BINARY n.text0_0 IN(BINARY s.en,BINARY s.zh,BINARY s.bi);
UPDATE npc_text n JOIN reborn_wdn1d1_texts s ON s.id=n.ID
 SET n.text0_1=s.bi
 WHERE BINARY n.text0_1 IN(BINARY s.en,BINARY s.zh,BINARY s.bi);
UPDATE npc_text_locale l JOIN reborn_wdn1d1_texts s ON s.id=l.ID
 SET l.Text0_0=s.bi
 WHERE l.Locale IN('zhCN','enUS') AND
 (l.Text0_0 IS NULL OR l.Text0_0='' OR BINARY l.Text0_0 IN(BINARY s.en,BINARY s.zh,BINARY s.bi));
UPDATE npc_text_locale l JOIN reborn_wdn1d1_texts s ON s.id=l.ID
 SET l.Text0_1=s.bi
 WHERE l.Locale IN('zhCN','enUS') AND BINARY l.Text0_1 IN(BINARY s.en,BINARY s.zh,BINARY s.bi);
 SELECT s.id,'zhCN',s.bi FROM reborn_wdn1d1_texts s JOIN npc_text n ON n.ID=s.id
 LEFT JOIN npc_text_locale l ON l.ID=s.id AND l.Locale='zhCN'
 WHERE l.ID IS NULL AND BINARY n.text0_0=BINARY s.bi;
COMMIT;
SELECT COUNT(*) AS bilingual_fixed_rows FROM npc_text n JOIN reborn_wdn1d1_texts s ON s.id=n.ID WHERE BINARY n.text0_0=BINARY s.bi;
SELECT s.id AS unchanged_custom_or_missing_text FROM reborn_wdn1d1_texts s LEFT JOIN npc_text n ON n.ID=s.id WHERE n.ID IS NULL OR BINARY n.text0_0<>BINARY s.bi;
DROP TEMPORARY TABLE reborn_wdn1d1_texts;

END$$
DELIMITER ;
CALL reborn_wdn1d1_localize();
DROP PROCEDURE reborn_wdn1d1_localize;
